INSERT INTO public.books(slug,title,author,genre,description,synopsis,cover_url,featured,source,discussion_prompts,total_pages) VALUES
('the-great-gatsby','The Great Gatsby','F. Scott Fitzgerald','Literary Fiction','An enduring portrait of aspiration, wealth, and the American dream.','A classic exploration of aspiration, social class, and the distance between dreams and reality in Jazz Age America.','/__l5e/assets-v1/128d4bf1-ba6f-4383-a570-3179f1d669ef/gatsby.webp',true,'editorial','["How does wealth shape our understanding of success?","When does aspiration become an illusion?"]',180),
('pride-and-prejudice','Pride and Prejudice','Jane Austen','Romance','A witty exploration of first impressions, social expectations, and love.','Austen examines the influence of class, family expectations, and personal judgment on relationships.','/__l5e/assets-v1/f4d9152a-92ed-4059-9c17-e3517887571e/pride.webp',true,'editorial','["How do first impressions limit our understanding of others?","What makes a relationship equal?"]',432),
('frankenstein','Frankenstein','Mary Shelley','Fantasy','A thought-provoking classic about creation and responsibility.','Shelley explores the moral responsibility of a creator, the consequences of ambition, and the human need for belonging.','/__l5e/assets-v1/376ed528-30a0-4c11-b1ac-e3db361d5015/frankenstein.webp',true,'editorial','["What responsibilities come with creating something new?","How does isolation shape identity?"]',280),
('little-women','Little Women','Louisa May Alcott','Literary Fiction','A timeless reflection on family, ambition, and growing into yourself.','A classic novel exploring sisterhood, individual aspirations, and the changing responsibilities of growing up.','/__l5e/assets-v1/7ae5a752-1125-4241-be84-f3f266b5fde9/little-women.webp',true,'editorial','["How can personal ambition coexist with family responsibilities?","What does growing up mean to you?"]',480),
('jane-eyre','Jane Eyre','Charlotte Brontë','Romance','An exploration of independence, integrity, and belonging.','A literary classic addressing personal independence, moral conviction, love, and the search for belonging.','/__l5e/assets-v1/54e956de-ac27-49a9-8658-6663acc506ac/jane-eyre.webp',false,'editorial','["How does independence influence love?","When should integrity take priority over belonging?"]',532),
('the-secret-garden','The Secret Garden','Frances Hodgson Burnett','Fantasy','A celebration of nature, friendship, and renewal.','A classic reflection on the restorative power of nature and the possibilities of friendship and emotional growth.','/__l5e/assets-v1/ac236917-2380-4f6d-9955-31acb5d492da/secret-garden.webp',false,'editorial','["What role does nature play in emotional renewal?","How can friendship change our perspective?"]',288);
