CREATE POLICY author_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='author-materials' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY author_read_upload ON storage.objects FOR SELECT TO authenticated USING(bucket_id='author-materials' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
